<?php
declare(strict_types=1); namespace App\Http\Controllers\Classrooms; use App\Http\Controllers\Controller; use App\Http\Requests\Classrooms\AddClassroomMembersRequest; use App\Models\{Classroom,ClassroomMembership,Student}; use App\Services\Classrooms\ClassroomMembershipService; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class ClassroomMemberController extends Controller {public function index(Request $r,Classroom $classroom):View{$r->user()->can('classrooms.manage-students')?:abort(403);$placed=ClassroomMembership::where('academic_year_id',$classroom->academic_year_id)->where('status','active')->select('student_id');$available=Student::where('status','active')->whereNotIn('id',$placed)->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('full_name','like',"%$v%")->orWhere('nisn','like',"%$v%")->orWhere('nik','like',"%$v%")))->when($r->gender,fn($q,$v)=>$q->where('gender',$v))->when($r->classroom_label,fn($q,$v)=>$q->where('classroom_label',$v))->paginate(15);$members=$classroom->activeMemberships()->with('student')->get();return view('classrooms.members',compact('classroom','available','members'));}public function store(AddClassroomMembersRequest $r,Classroom $classroom,ClassroomMembershipService $s):RedirectResponse{$result=$s->addMany($r->user(),$classroom,$r->validated('student_ids'));return back()->with('success',"{$result['added']} siswa berhasil dimasukkan.")->with('member_errors',$result['errors']);}public function destroy(Request $r,Classroom $classroom,ClassroomMembership $membership,ClassroomMembershipService $s):RedirectResponse{$r->user()->can('classrooms.manage-students')?:abort(403);abort_unless($membership->classroom_id===$classroom->id,404);$s->remove($r->user(),$membership,$r->input('notes'));return back()->with('success','Siswa berhasil dikeluarkan dari rombel.');}}
